import itertools
V = ['P', 'Q', 'R', 'S', 'T', 'U']
ok = []
for vals in itertools.product(range(5), repeat=len(V)):
    P, Q, R, S, T, U = vals
    if P >= Q == R > S and R <= T < U:
        ok.append(vals)
def holds(f):
    return all(f(*v) for v in ok)
c1 = holds(lambda P, Q, R, S, T, U: P > S)
